    #[cfg(target_arch = "aarch64")]
    fn get_prepared_weight(
        &self,
        offset: usize,
        len: usize,
        k: usize,
        n: usize,
    ) -> std::sync::Arc<lele::kernels::PreparedWeightsArm> {
        let key = (offset, len);
        {
            let cache = self.prepared_weights_cache.borrow();
            if let Some(pw) = cache.get(&key) {
                return pw.clone();
            }
        }
        let raw_bytes = &self.data[offset..offset + len];
        let pw = std::sync::Arc::new(lele::kernels::prepare_weights_arm(raw_bytes, k, n));
        self.prepared_weights_cache
            .borrow_mut()
            .insert(key, pw.clone());
        pw
    }
